const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const targetDate = ee.Date('2025-08-03');
    const geometry = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.and(
        ee.Filter.eq('ADM0_NAME', 'Canada'),
        ee.Filter.eq('ADM1_NAME', 'Manitoba')
      ))
      .first()
      .geometry();

    if (!geometry) {
      console.log("Error: Could not retrieve Manitoba geometry.");
      console.log("D"); // Indicates an issue with data retrieval/naming
      return;
    }

    // 2. Data Acquisition & Check
    // Use the FIRMS (Fire Information for Resource Management System) collection
    // Note: Earth Engine data is historical. The question asks for a future date (2025-08-03).
    // This will likely result in an empty collection and thus C1.
    const fires = ee.ImageCollection('FIRMS')
      .filterDate(targetDate, targetDate.advance(1, 'day'))
      .filterBounds(geometry);

    const firesCount = await fires.size().getInfo();

    console.log(`Manitoba geometry defined.`);
    console.log(`Searching for fires on ${targetDate.format('YYYY-MM-DD').getInfo()}...`);
    console.log(`Initial fire detections found: ${firesCount}`);

    // Check if the collection is empty due to future date or no data
    if (firesCount === 0) {
      // Check the typical date range of FIRMS to confirm it's a future date issue.
      // FIRMS data usually goes up to the present or very recent past.
      const firmsInfo = await ee.ImageCollection('FIRMS').first().getInfo(); // Get info on first image
      const firmsStartTime = ee.Date(firmsInfo.system_time_start);
      const firmsEndTime = ee.Date(firmsInfo.system_time_end);
      const targetTime = targetDate.millis();

      if (targetTime > ee.Date(Date.now()).millis()) { // Check if targetDate is in the future relative to now
         console.log(`The target date ${targetDate.format('YYYY-MM-DD').getInfo()} is in the future.`);
         console.log("C1"); // Empty Collection due to future date
         return;
      }

      // If not a future date, but still empty (e.g., no fires on that date), we proceed
      // to check confidence, which for 0 fires will still result in 0.
    }

    // 3. Processing: Filter by confidence for "active fires"
    // FIRMS dataset 'confidence' band typically has string values: 'low', 'nominal', 'high'.
    // We consider 'high' confidence as clear active fires.
    const highConfidenceFires = fires.filter(ee.Filter.eq('confidence', 'h')); // 'h' for high confidence

    const highConfFiresCount = await highConfidenceFires.size().getInfo();
    console.log(`High confidence fires found: ${highConfFiresCount}`);

    // This block is for C2, but for point data, if highConfFiresCount is 0,
    // it directly means no valid fires, which is a valid zero.
    // So, it falls into the A/B category rather than a processing failure (C2).

    // 4. Calculation: Total count of high confidence fires
    const finalFireCount = highConfFiresCount;

    // 5. Validation & Final Answer
    console.log(`Final count of active fires in Manitoba on Aug 3, 2025: ${finalFireCount}`);

    if (finalFireCount === null || isNaN(finalFireCount)) {
      console.log("C3"); // Calculation failure
    } else if (finalFireCount > 30) {
      console.log("A"); // Yes, more than 30 fires
    } else {
      console.log("B"); // No, 30 or fewer fires
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    // Attempt to categorize common errors
    if (error.message.includes("ImageCollection has no images")) {
      console.log("C1"); // No images found (though handled above for future date)
    } else if (error.message.includes("does not exist") || error.message.includes("has no band")) {
      console.log("D"); // Incorrect collection/band name or syntax
    } else if (error.message.includes("MemoryLimitExceeded")) {
      console.log("D"); // Memory issue
    } else {
      console.log("D"); // General unexpected error
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
